```html
<cu-color-picker value="#1774A4" id="colorForm"></cu-color-picker>

<script>
  const cp = document.getElementById('colorForm');
  cp.addEventListener('update:modelValue', (e) => {
    document.body.style.borderColor = e.detail;
  });
</script>
```

